{#
  Project Executive Print Format — Operativo v0.2 (REDUCIDO).
  Base literal del prototipo. Se elimina únicamente: el detalle Task-by-Task (apéndice de Tasks,
  Responsables/asignaciones, dependencias, archivos por Task, y las tablas de Tasks dentro de fases),
  la sección de costos, y todo cálculo de avance lineal (planned_progress / phase_planned) con su
  desviación derivada. Único avance general: Project.percent_complete. El resto se conserva literal.
#}
{% set status_labels = {
  'Open': 'Abierta',
  'Working': 'En ejecución',
  'Pending Review': 'En revisión',
  'Overdue': 'Vencida',
  'Template': 'Plantilla',
  'Completed': 'Terminada',
  'Cancelled': 'Cancelada'
} %}
{% set project_status_labels = {
  'Open': 'Abierto',
  'On hold': 'En pausa',
  'Completed': 'Terminado',
  'Cancelled': 'Cancelado'
} %}
{% set priority_labels = {
  'Low': 'Baja',
  'Medium': 'Media',
  'High': 'Alta',
  'Urgent': 'Urgente'
} %}

{% set tasks = frappe.get_all(
  'Task',
  filters={'project': doc.name, 'is_template': 0},
  fields=[
    'name', 'subject', 'status', 'priority', 'task_weight', 'parent_task',
    'is_group', 'exp_start_date', 'exp_end_date', 'expected_time', 'progress',
    'is_milestone', 'description', 'act_start_date', 'act_end_date', 'actual_time',
    'total_costing_amount', 'total_billing_amount', 'completed_on', 'completed_by',
    'lft', 'rgt'
  ],
  order_by='lft asc, creation asc'
) %}

{% set leaf_tasks = tasks | selectattr('is_group', 'equalto', 0) | list %}
{% set top_groups = tasks | selectattr('is_group', 'equalto', 1) | rejectattr('parent_task') | list %}
{% set top_leaf_tasks = leaf_tasks | rejectattr('parent_task') | list %}

{% set completed_tasks = leaf_tasks | selectattr('status', 'equalto', 'Completed') | list %}
{% set open_tasks = leaf_tasks | selectattr('status', 'equalto', 'Open') | list %}
{% set working_tasks = leaf_tasks | selectattr('status', 'equalto', 'Working') | list %}
{% set review_tasks = leaf_tasks | selectattr('status', 'equalto', 'Pending Review') | list %}
{% set overdue_tasks = leaf_tasks | selectattr('status', 'equalto', 'Overdue') | list %}
{% set cancelled_tasks = leaf_tasks | selectattr('status', 'equalto', 'Cancelled') | list %}
{% set milestone_tasks = leaf_tasks | selectattr('is_milestone', 'equalto', 1) | list %}
{% set active_tasks = open_tasks + working_tasks + review_tasks + overdue_tasks %}

{% set expected_hours = leaf_tasks | sum(attribute='expected_time') %}
{% set actual_hours = leaf_tasks | sum(attribute='actual_time') %}
{% set total_leaf_tasks = leaf_tasks | length %}
{% set actual_progress = doc.percent_complete or 0 %}

{% set completed_pct = ((completed_tasks | length) * 100 / total_leaf_tasks) if total_leaf_tasks else 0 %}
{% set working_pct = ((working_tasks | length) * 100 / total_leaf_tasks) if total_leaf_tasks else 0 %}
{% set review_pct = ((review_tasks | length) * 100 / total_leaf_tasks) if total_leaf_tasks else 0 %}
{% set overdue_pct = ((overdue_tasks | length) * 100 / total_leaf_tasks) if total_leaf_tasks else 0 %}
{% set open_pct = ((open_tasks | length) * 100 / total_leaf_tasks) if total_leaf_tasks else 0 %}
{% set cancelled_pct = ((cancelled_tasks | length) * 100 / total_leaf_tasks) if total_leaf_tasks else 0 %}

{% set hours_scale = expected_hours if expected_hours >= actual_hours else actual_hours %}
{% if not hours_scale %}{% set hours_scale = 1 %}{% endif %}
{% set expected_hours_pct = (expected_hours * 100 / hours_scale) if hours_scale else 0 %}
{% set actual_hours_pct = (actual_hours * 100 / hours_scale) if hours_scale else 0 %}

{% set customer_name = frappe.db.get_value('Customer', doc.customer, 'customer_name') if doc.customer else '' %}
{% set company_logo = frappe.db.get_value('Company', doc.company, 'company_logo') if doc.company else '' %}
{# Logo solo si la Company lo tiene (se elimina el archivo hardcodeado del prototipo, inexistente aquí y que
   rompe el PDF: wkhtmltopdf no resuelve el host del <img> externo). El resto del prototipo queda literal. #}
{% set company_logo_url = frappe.utils.get_url(company_logo) if company_logo else '' %}

<style>
  @page { size: A4 landscape; margin: 9mm 9mm 11mm 9mm; }
  .print-format { font-family: Arial, Helvetica, sans-serif; color: #24313d; font-size: 9.5pt; line-height: 1.35; }
  .pe-report * { box-sizing: border-box; }
  .pe-report { width: 100%; }
  .pe-header { background: #173955; color: #fff !important; padding: 16px 18px; border-radius: 7px; margin-bottom: 10px; }
  .pe-header, .pe-header *, .pe-header a, .pe-header h1, .pe-header .subtitle, .pe-header-table td, .pe-header-table .label, .pe-header-table .value { color: #fff !important; }
  .pe-header-main { width: 100%; border: 0; border-collapse: collapse; table-layout: fixed; }
  .pe-header-main td { border: 0; padding: 0; vertical-align: middle; }
  .pe-header-main .pe-header-title { width: 74%; padding-right: 14px; }
  .pe-header-main .pe-header-logo-cell { width: 26%; text-align: right; }
  .pe-header h1 { margin: 0 0 4px; font-size: 22px; line-height: 1.2; color: #fff !important; }
  .pe-header h1 a { color: #fff !important; text-decoration: none !important; }
  .pe-header .subtitle { color: #d6e5ef !important; font-size: 10pt; }
  .pe-logo-box { display: inline-block; min-width: 95px; max-width: 180px; min-height: 44px; padding: 7px 10px; background: #fff; border-radius: 5px; text-align: center; vertical-align: middle; }
  .pe-company-logo { display: block; max-width: 160px; max-height: 58px; width: auto; height: auto; margin: 0 auto; }
  .pe-header-table { width: 100%; border: 0; margin-top: 10px; }
  .pe-header-table td { border: 0; color: #fff !important; padding: 2px 12px 2px 0; vertical-align: top; }
  .pe-header-table .label { color: #bcd0dd !important; font-size: 7.5pt; text-transform: uppercase; letter-spacing: .04em; }
  .pe-header-table .value { color: #fff !important; font-weight: 700; font-size: 10pt; }

  .pe-section { margin-top: 13px; page-break-inside: avoid; }
  .pe-section-title { margin: 0 0 7px; padding: 6px 8px; background: #e7eef4; color: #173955; border-left: 5px solid #2f6f9f; font-size: 12pt; font-weight: 700; }
  .pe-small-title { margin: 9px 0 5px; color: #234f70; font-size: 10.5pt; font-weight: 700; }

  .pe-kpis { width: 100%; border-collapse: separate; border-spacing: 5px; table-layout: fixed; margin: 0 -5px 4px; }
  .pe-kpis td { background: #f4f7f9; border: 1px solid #d8e1e8; border-radius: 5px; padding: 9px 8px; text-align: center; vertical-align: middle; }
  .pe-kpis .number { display: block; color: #173955; font-size: 17pt; line-height: 1.05; font-weight: 700; }
  .pe-kpis .caption { display: block; color: #617383; font-size: 7.5pt; margin-top: 3px; text-transform: uppercase; }
  .pe-kpis .danger .number { color: #9b2c2c; }
  .pe-kpis .success .number { color: #2f6b3b; }

  .pe-meta { width: 100%; border-collapse: collapse; margin-bottom: 5px; }
  .pe-meta th, .pe-meta td { border: 1px solid #d7e0e7; padding: 6px 7px; vertical-align: top; }
  .pe-meta th { width: 14%; background: #f2f6f8; color: #536878; font-size: 7.5pt; text-transform: uppercase; }
  .pe-meta td { width: 19%; }

  .pe-table { width: 100%; border-collapse: collapse; page-break-inside: auto; }
  .pe-table thead { display: table-header-group; }
  .pe-table tr { page-break-inside: avoid; page-break-after: auto; }
  .pe-table th, .pe-table td { border: 1px solid #d5dee5; padding: 5px 6px; vertical-align: top; }
  .pe-table th { background: #173955; color: #fff; font-size: 7.5pt; text-transform: uppercase; letter-spacing: .02em; }
  .pe-table td { font-size: 8.5pt; }
  .pe-table .right { text-align: right; }
  .pe-table .center { text-align: center; }
  .pe-table .muted { color: #697b8a; }

  .pe-status { display: inline-block; padding: 2px 6px; border-radius: 10px; font-size: 7.5pt; font-weight: 700; white-space: nowrap; background: #e7edf1; color: #455d6e; }
  .pe-status.completed { background: #e4f1e6; color: #2f6b3b; }
  .pe-status.overdue { background: #f9dddd; color: #922f2f; }
  .pe-status.working { background: #e1eef8; color: #245c85; }
  .pe-status.pending-review { background: #fff1c8; color: #7a5a00; }
  .pe-status.cancelled { background: #ececec; color: #6b6b6b; }
  .pe-milestone { display: inline-block; margin-left: 4px; padding: 2px 5px; border-radius: 8px; background: #fce7d9; color: #8a4a21; font-size: 7pt; font-weight: 700; }

  .pe-notes { border: 1px solid #d8e1e8; background: #fbfcfd; padding: 9px 11px; border-left: 4px solid #4e89b3; }
  .pe-notes p:first-child { margin-top: 0; }
  .pe-notes p:last-child { margin-bottom: 0; }
  .pe-inline-list { margin: 3px 0 0; padding-left: 18px; }
  .pe-inline-list li { margin: 2px 0; }
  .pe-empty { color: #7a8b97; font-style: italic; }
  .pe-footnote { margin-top: 14px; padding-top: 7px; border-top: 1px solid #ccd7df; color: #6e7f8b; font-size: 7.5pt; }
  .pe-page-break { page-break-before: always; }

  .pe-chart-grid { width: 100%; border-collapse: separate; border-spacing: 7px; table-layout: fixed; margin: 0 -7px 2px; }
  .pe-chart-grid > tbody > tr > td { width: 33.333%; border: 1px solid #d5dee5; border-radius: 6px; background: #fbfcfd; padding: 10px; vertical-align: top; }
  .pe-chart-title { color: #173955; font-size: 10pt; font-weight: 700; margin: 0 0 3px; }
  .pe-chart-subtitle { color: #697b8a; font-size: 7.5pt; margin-bottom: 9px; min-height: 20px; }
  .pe-chart-row { margin: 7px 0 9px; }
  .pe-chart-row-head { width: 100%; border: 0; margin-bottom: 3px; }
  .pe-chart-row-head td { border: 0; padding: 0; font-size: 8pt; }
  .pe-chart-row-head td:last-child { text-align: right; font-weight: 700; color: #304d62; }
  .pe-bar-track { height: 11px; width: 100%; background: #e6edf2; border: 1px solid #d3dde5; border-radius: 6px; overflow: hidden; }
  .pe-bar-fill { height: 100%; min-width: 0; border-radius: 5px; }
  .pe-bar-fill.planned { background: #8fa6b7; }
  .pe-bar-fill.actual { background: #2f6f9f; }
  .pe-bar-fill.hours-plan { background: #6f91a8; }
  .pe-bar-fill.hours-real { background: #3f7faa; }

  .pe-stack { width: 100%; height: 16px; border: 1px solid #ccd8e0; border-radius: 8px; overflow: hidden; white-space: nowrap; font-size: 0; background: #edf2f5; }
  .pe-stack-seg { height: 100%; display: inline-block; vertical-align: top; }
  .pe-stack-seg.completed { background: #4e8758; }
  .pe-stack-seg.working { background: #3f7faa; }
  .pe-stack-seg.review { background: #c39a31; }
  .pe-stack-seg.overdue { background: #b34848; }
  .pe-stack-seg.open { background: #8ea1af; }
  .pe-stack-seg.cancelled { background: #c8c8c8; }
  .pe-legend { margin-top: 8px; }
  .pe-legend-item { display: inline-block; margin: 0 8px 4px 0; font-size: 7.3pt; color: #536878; white-space: nowrap; }
  .pe-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; margin-right: 3px; vertical-align: 1px; }
  .pe-dot.completed { background: #4e8758; }
  .pe-dot.working { background: #3f7faa; }
  .pe-dot.review { background: #c39a31; }
  .pe-dot.overdue { background: #b34848; }
  .pe-dot.open { background: #8ea1af; }
  .pe-dot.cancelled { background: #c8c8c8; }

  .pe-donut-layout { width: 100%; border: 0; margin: 0 0 5px; }
  .pe-donut-layout td { border: 0; padding: 0; vertical-align: middle; }
  .pe-donut-cell { width: 45%; text-align: center; }
  .pe-donut-legend-cell { width: 55%; padding-left: 5px !important; }
  .pe-donut { position: relative; width: 105px; height: 105px; margin: 0 auto; }
  .pe-donut svg { width: 105px; height: 105px; display: block; }
  .pe-donut-track { fill: none; stroke: #e6edf2; stroke-width: 5.6; }
  .pe-donut-segment { fill: none; stroke-width: 5.6; stroke-linecap: butt; }
  .pe-donut-segment.completed { stroke: #4e8758; }
  .pe-donut-segment.working { stroke: #3f7faa; }
  .pe-donut-segment.review { stroke: #c39a31; }
  .pe-donut-segment.overdue { stroke: #b34848; }
  .pe-donut-segment.open { stroke: #8ea1af; }
  .pe-donut-segment.cancelled { stroke: #c8c8c8; }
  .pe-donut-center { position: absolute; left: 0; right: 0; top: 33px; text-align: center; color: #173955; }
  .pe-donut-center strong { display: block; font-size: 17pt; line-height: 1; color: #173955; }
  .pe-donut-center span { display: block; margin-top: 3px; color: #687b89; font-size: 7pt; text-transform: uppercase; }
  .pe-donut-legend-cell .pe-legend-item { display: block; margin: 0 0 4px; }

  .pe-variance { margin-top: 8px; padding: 5px 7px; border-radius: 4px; background: #edf3f7; color: #34556d; font-size: 8pt; }
  .pe-variance.behind { background: #f8e1e1; color: #8f3030; }
  .pe-variance.ahead { background: #e5f1e7; color: #2f6b3b; }

  .pe-phase { margin: 12px 0 14px; border: 1px solid #cfdbe3; border-radius: 6px; page-break-inside: avoid; }
  .pe-phase-header { background: #edf3f7; padding: 8px 10px; border-bottom: 1px solid #cfdbe3; }
  .pe-phase-header table { width: 100%; border: 0; }
  .pe-phase-header td { border: 0; padding: 0; vertical-align: middle; }
  .pe-phase-header h3 { margin: 0; color: #173955; font-size: 12pt; }
  .pe-phase-kpi { text-align: right; color: #506575; font-size: 8pt; }
  .pe-phase-body { padding: 8px; }

  .pe-task-code { color: #2f658c; font-family: Consolas, monospace; font-weight: 700; white-space: nowrap; }
  .pe-phase-bars { margin-top: 7px; }
  .pe-phase-bars table { width: 100%; border: 0; }
  .pe-phase-bars td { border: 0; padding: 2px 0; font-size: 7.5pt; vertical-align: middle; }
  .pe-phase-bars .bar-label { width: 58px; color: #536878; }
  .pe-phase-bars .bar-value { width: 42px; text-align: right; font-weight: 700; color: #304d62; }
  .pe-phase-bars .pe-bar-track { height: 8px; }

  .pe-link-task { color: #245f89; text-decoration: none; font-weight: 700; border-bottom: 1px dotted #7e9db4; }
  .pe-link-task:hover { color: #173955; border-bottom-style: solid; }

  a { color: #245f89; text-decoration: none; }
</style>

<div class="pe-report">
  <div class="pe-header">
    <table class="pe-header-main">
      <tr>
        <td class="pe-header-title">
          <h1><a href="{{ frappe.utils.get_url_to_form('Project', doc.name) }}" title="Abrir Project en ERPNext">{{ doc.project_name or doc.name }}</a></h1>
          <div class="subtitle">Reporte ejecutivo del proyecto · {{ doc.name }}</div>
        </td>
        {% if company_logo_url %}
        <td class="pe-header-logo-cell">
          <span class="pe-logo-box"><img class="pe-company-logo" src="{{ company_logo_url }}" alt="Logo de {{ doc.company or 'la empresa' }}"></span>
        </td>
        {% endif %}
      </tr>
    </table>
    <table class="pe-header-table">
      <tr>
        <td><div class="label">Cliente</div><div class="value">{{ customer_name or doc.customer or 'No definido' }}</div></td>
        <td><div class="label">Empresa</div><div class="value">{{ doc.company or 'No definida' }}</div></td>
        <td><div class="label">Tipo</div><div class="value">{{ doc.project_type or 'No definido' }}</div></td>
        <td><div class="label">Estado</div><div class="value">{{ project_status_labels.get(doc.status, doc.status) }}</div></td>
        <td><div class="label">Fecha de corte</div><div class="value">{{ frappe.format_date(frappe.utils.nowdate()) }}</div></td>
      </tr>
    </table>
  </div>

  <table class="pe-kpis">
    <tr>
      <td><span class="number">{{ frappe.format(doc.percent_complete or 0, {'fieldtype': 'Percent'}) }}</span><span class="caption">Avance general</span></td>
      <td><span class="number">{{ leaf_tasks | length }}</span><span class="caption">Tasks</span></td>
      <td class="success"><span class="number">{{ completed_tasks | length }}</span><span class="caption">Terminadas</span></td>
      <td><span class="number">{{ active_tasks | length }}</span><span class="caption">Abiertas / activas</span></td>
      <td class="danger"><span class="number">{{ overdue_tasks | length }}</span><span class="caption">Vencidas</span></td>
      <td><span class="number">{{ milestone_tasks | length }}</span><span class="caption">Hitos</span></td>
      <td><span class="number">{{ '%.1f' | format(expected_hours or 0) }}</span><span class="caption">Horas previstas</span></td>
      <td><span class="number">{{ '%.1f' | format(actual_hours or 0) }}</span><span class="caption">Horas registradas</span></td>
    </tr>
  </table>

  <div class="pe-section">
    <div class="pe-section-title">Indicadores gráficos</div>
    <table class="pe-chart-grid">
      <tr>
        <td>
          <div class="pe-chart-title">Avance del proyecto</div>
          <div class="pe-chart-subtitle">Avance oficial del proyecto según ERPNext (Project.percent_complete).</div>

          <div class="pe-chart-row">
            <table class="pe-chart-row-head"><tr><td>Avance registrado</td><td>{{ '%.1f' | format(actual_progress) }}%</td></tr></table>
            <div class="pe-bar-track"><div class="pe-bar-fill actual" style="width: {{ '%.2f' | format(actual_progress) }}%"></div></div>
          </div>
        </td>

        <td>
          <div class="pe-chart-title">Distribución de Tasks por estado</div>
          <div class="pe-chart-subtitle">Considera únicamente Tasks hoja; excluye Tasks padre utilizadas como fases.</div>
          {% if total_leaf_tasks %}
            {% set offset_completed = 0 %}
            {% set offset_working = completed_pct %}
            {% set offset_review = completed_pct + working_pct %}
            {% set offset_overdue = completed_pct + working_pct + review_pct %}
            {% set offset_open = completed_pct + working_pct + review_pct + overdue_pct %}
            {% set offset_cancelled = completed_pct + working_pct + review_pct + overdue_pct + open_pct %}
            <table class="pe-donut-layout">
              <tr>
                <td class="pe-donut-cell">
                  <div class="pe-donut">
                    <svg viewBox="0 0 42 42" role="img" aria-label="Distribución de Tasks por estado">
                      <circle class="pe-donut-track" cx="21" cy="21" r="15.9155"></circle>
                      {% if completed_pct %}<circle class="pe-donut-segment completed" cx="21" cy="21" r="15.9155" pathLength="100" stroke-dasharray="{{ '%.4f'|format(completed_pct) }} {{ '%.4f'|format(100-completed_pct) }}" stroke-dashoffset="{{ '%.4f'|format(-offset_completed) }}" transform="rotate(-90 21 21)"></circle>{% endif %}
                      {% if working_pct %}<circle class="pe-donut-segment working" cx="21" cy="21" r="15.9155" pathLength="100" stroke-dasharray="{{ '%.4f'|format(working_pct) }} {{ '%.4f'|format(100-working_pct) }}" stroke-dashoffset="{{ '%.4f'|format(-offset_working) }}" transform="rotate(-90 21 21)"></circle>{% endif %}
                      {% if review_pct %}<circle class="pe-donut-segment review" cx="21" cy="21" r="15.9155" pathLength="100" stroke-dasharray="{{ '%.4f'|format(review_pct) }} {{ '%.4f'|format(100-review_pct) }}" stroke-dashoffset="{{ '%.4f'|format(-offset_review) }}" transform="rotate(-90 21 21)"></circle>{% endif %}
                      {% if overdue_pct %}<circle class="pe-donut-segment overdue" cx="21" cy="21" r="15.9155" pathLength="100" stroke-dasharray="{{ '%.4f'|format(overdue_pct) }} {{ '%.4f'|format(100-overdue_pct) }}" stroke-dashoffset="{{ '%.4f'|format(-offset_overdue) }}" transform="rotate(-90 21 21)"></circle>{% endif %}
                      {% if open_pct %}<circle class="pe-donut-segment open" cx="21" cy="21" r="15.9155" pathLength="100" stroke-dasharray="{{ '%.4f'|format(open_pct) }} {{ '%.4f'|format(100-open_pct) }}" stroke-dashoffset="{{ '%.4f'|format(-offset_open) }}" transform="rotate(-90 21 21)"></circle>{% endif %}
                      {% if cancelled_pct %}<circle class="pe-donut-segment cancelled" cx="21" cy="21" r="15.9155" pathLength="100" stroke-dasharray="{{ '%.4f'|format(cancelled_pct) }} {{ '%.4f'|format(100-cancelled_pct) }}" stroke-dashoffset="{{ '%.4f'|format(-offset_cancelled) }}" transform="rotate(-90 21 21)"></circle>{% endif %}
                    </svg>
                    <div class="pe-donut-center"><strong>{{ total_leaf_tasks }}</strong><span>Tasks</span></div>
                  </div>
                </td>
                <td class="pe-donut-legend-cell">
                  <span class="pe-legend-item"><span class="pe-dot completed"></span>Terminadas {{ completed_tasks|length }}</span>
                  <span class="pe-legend-item"><span class="pe-dot working"></span>En ejecución {{ working_tasks|length }}</span>
                  <span class="pe-legend-item"><span class="pe-dot review"></span>En revisión {{ review_tasks|length }}</span>
                  <span class="pe-legend-item"><span class="pe-dot overdue"></span>Vencidas {{ overdue_tasks|length }}</span>
                  <span class="pe-legend-item"><span class="pe-dot open"></span>Abiertas {{ open_tasks|length }}</span>
                  {% if cancelled_tasks %}<span class="pe-legend-item"><span class="pe-dot cancelled"></span>Canceladas {{ cancelled_tasks|length }}</span>{% endif %}
                </td>
              </tr>
            </table>
            <div class="pe-stack" title="La misma distribución mostrada como barra apilada">
              <span class="pe-stack-seg completed" style="width: {{ '%.2f' | format(completed_pct) }}%"></span>
              <span class="pe-stack-seg working" style="width: {{ '%.2f' | format(working_pct) }}%"></span>
              <span class="pe-stack-seg review" style="width: {{ '%.2f' | format(review_pct) }}%"></span>
              <span class="pe-stack-seg overdue" style="width: {{ '%.2f' | format(overdue_pct) }}%"></span>
              <span class="pe-stack-seg open" style="width: {{ '%.2f' | format(open_pct) }}%"></span>
              <span class="pe-stack-seg cancelled" style="width: {{ '%.2f' | format(cancelled_pct) }}%"></span>
            </div>
          {% else %}
            <div class="pe-empty">No existen Tasks hoja.</div>
          {% endif %}
        </td>

        <td>
          <div class="pe-chart-title">Horas planificadas frente a registradas</div>
          <div class="pe-chart-subtitle">Las horas reales dependen de Timesheets asociados a las Tasks.</div>
          <div class="pe-chart-row">
            <table class="pe-chart-row-head"><tr><td>Horas previstas</td><td>{{ '%.1f' | format(expected_hours or 0) }}</td></tr></table>
            <div class="pe-bar-track"><div class="pe-bar-fill hours-plan" style="width: {{ '%.2f' | format(expected_hours_pct) }}%"></div></div>
          </div>
          <div class="pe-chart-row">
            <table class="pe-chart-row-head"><tr><td>Horas registradas</td><td>{{ '%.1f' | format(actual_hours or 0) }}</td></tr></table>
            <div class="pe-bar-track"><div class="pe-bar-fill hours-real" style="width: {{ '%.2f' | format(actual_hours_pct) }}%"></div></div>
          </div>
          {% set hours_variance = actual_hours - expected_hours %}
          <div class="pe-variance {% if hours_variance > 0 %}behind{% endif %}">
            Diferencia: <strong>{{ '%+.1f' | format(hours_variance) }} horas</strong>
          </div>
        </td>
      </tr>
    </table>
  </div>


  <div class="pe-section">
    <div class="pe-section-title">Identificación y calendario</div>
    <table class="pe-meta">
      <tr>
        <th>Inicio previsto</th><td>{{ frappe.format_date(doc.expected_start_date) if doc.expected_start_date else 'No definido' }}</td>
        <th>Fin previsto</th><td>{{ frappe.format_date(doc.expected_end_date) if doc.expected_end_date else 'No definido' }}</td>
        <th>Prioridad</th><td>{{ priority_labels.get(doc.priority, doc.priority or 'No definida') }}</td>
      </tr>
      <tr>
        <th>Inicio real</th><td>{{ frappe.format_date(doc.actual_start_date) if doc.actual_start_date else 'Sin registro por Timesheet' }}</td>
        <th>Fin real</th><td>{{ frappe.format_date(doc.actual_end_date) if doc.actual_end_date else 'Sin registro por Timesheet' }}</td>
        <th>Método de avance</th><td>{{ doc.percent_complete_method or 'No definido' }}</td>
      </tr>
      <tr>
        <th>Departamento</th><td>{{ doc.department or 'No definido' }}</td>
        <th>Orden de venta</th><td>{{ doc.sales_order or 'No relacionada' }}</td>
        <th>Última actualización</th><td>{{ frappe.format(doc.modified, {'fieldtype': 'Datetime'}) }}</td>
      </tr>
    </table>
  </div>

  {% if doc.notes %}
  <div class="pe-section">
    <div class="pe-section-title">Resumen y notas del proyecto</div>
    <div class="pe-notes">{{ doc.notes | safe }}</div>
  </div>
  {% endif %}

  <div class="pe-section">
    <div class="pe-section-title">Estado ejecutivo de las actividades</div>
    <table class="pe-table">
      <thead>
        <tr>
          <th style="width:13%">Situación</th>
          <th>Actividades principales</th>
          <th style="width:9%">Cantidad</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td><span class="pe-status completed">Terminadas</span></td>
          <td>
            {% if completed_tasks %}
              {% for task in completed_tasks[:12] %}<a class="pe-link-task" href="{{ frappe.utils.get_url_to_form('Task', task.name) }}">{{ task.subject }}</a>{% if not loop.last %}; {% endif %}{% endfor %}
              {% if completed_tasks|length > 12 %}<span class="muted"> · y {{ completed_tasks|length - 12 }} más</span>{% endif %}
            {% else %}<span class="pe-empty">Ninguna.</span>{% endif %}
          </td>
          <td class="center">{{ completed_tasks | length }}</td>
        </tr>
        <tr>
          <td><span class="pe-status working">En ejecución</span></td>
          <td>
            {% if working_tasks %}
              {% for task in working_tasks[:12] %}<a class="pe-link-task" href="{{ frappe.utils.get_url_to_form('Task', task.name) }}">{{ task.subject }}</a>{% if not loop.last %}; {% endif %}{% endfor %}
              {% if working_tasks|length > 12 %}<span class="muted"> · y {{ working_tasks|length - 12 }} más</span>{% endif %}
            {% else %}<span class="pe-empty">Ninguna.</span>{% endif %}
          </td>
          <td class="center">{{ working_tasks | length }}</td>
        </tr>
        <tr>
          <td><span class="pe-status pending-review">En revisión</span></td>
          <td>
            {% if review_tasks %}
              {% for task in review_tasks[:12] %}<a class="pe-link-task" href="{{ frappe.utils.get_url_to_form('Task', task.name) }}">{{ task.subject }}</a>{% if not loop.last %}; {% endif %}{% endfor %}
              {% if review_tasks|length > 12 %}<span class="muted"> · y {{ review_tasks|length - 12 }} más</span>{% endif %}
            {% else %}<span class="pe-empty">Ninguna.</span>{% endif %}
          </td>
          <td class="center">{{ review_tasks | length }}</td>
        </tr>
        <tr>
          <td><span class="pe-status overdue">Vencidas</span></td>
          <td>
            {% if overdue_tasks %}
              {% for task in overdue_tasks[:12] %}<a class="pe-link-task" href="{{ frappe.utils.get_url_to_form('Task', task.name) }}">{{ task.subject }}</a>{% if not loop.last %}; {% endif %}{% endfor %}
              {% if overdue_tasks|length > 12 %}<span class="muted"> · y {{ overdue_tasks|length - 12 }} más</span>{% endif %}
            {% else %}<span class="pe-empty">Ninguna.</span>{% endif %}
          </td>
          <td class="center">{{ overdue_tasks | length }}</td>
        </tr>
        <tr>
          <td><span class="pe-status">Abiertas</span></td>
          <td>
            {% if open_tasks %}
              {% for task in open_tasks[:12] %}<a class="pe-link-task" href="{{ frappe.utils.get_url_to_form('Task', task.name) }}">{{ task.subject }}</a>{% if not loop.last %}; {% endif %}{% endfor %}
              {% if open_tasks|length > 12 %}<span class="muted"> · y {{ open_tasks|length - 12 }} más</span>{% endif %}
            {% else %}<span class="pe-empty">Ninguna.</span>{% endif %}
          </td>
          <td class="center">{{ open_tasks | length }}</td>
        </tr>
      </tbody>
    </table>
  </div>

  {% if milestone_tasks %}
  <div class="pe-section">
    <div class="pe-section-title">Hitos</div>
    <table class="pe-table">
      <thead>
        <tr>
          <th style="width:13%">Task</th>
          <th>Hito</th>
          <th style="width:12%">Estado</th>
          <th style="width:12%">Fecha prevista</th>
          <th style="width:12%">Fecha cumplida</th>
          <th style="width:9%">Avance</th>
        </tr>
      </thead>
      <tbody>
        {% for task in milestone_tasks %}
        <tr>
          <td class="pe-task-code"><a class="pe-link-task" href="{{ frappe.utils.get_url_to_form('Task', task.name) }}" title="Abrir Task en ERPNext">{{ task.name }}</a></td>
          <td><a class="pe-link-task" href="{{ frappe.utils.get_url_to_form('Task', task.name) }}" title="Abrir Task en ERPNext">{{ task.subject }}</a></td>
          <td><span class="pe-status {{ task.status|lower|replace(' ', '-') }}">{{ status_labels.get(task.status, task.status) }}</span></td>
          <td>{{ frappe.format_date(task.exp_end_date) if task.exp_end_date else 'No definida' }}</td>
          <td>{{ frappe.format_date(task.completed_on) if task.completed_on else 'Pendiente' }}</td>
          <td class="right">{{ frappe.format(task.progress or 0, {'fieldtype': 'Percent'}) }}</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
  </div>
  {% endif %}

  <div class="pe-section">
    <div class="pe-section-title">Avance por fase o línea</div>

    {% if top_groups %}
      {% for phase in top_groups %}
        {% set phase_rows = tasks | selectattr('parent_task', 'equalto', phase.name) | list %}
        {% set phase_leaf_rows = phase_rows | selectattr('is_group', 'equalto', 0) | list %}
        {% set phase_done = phase_leaf_rows | selectattr('status', 'equalto', 'Completed') | list %}
        {% set phase_overdue = phase_leaf_rows | selectattr('status', 'equalto', 'Overdue') | list %}
        <div class="pe-phase">
          <div class="pe-phase-header">
            <table>
              <tr>
                <td><h3><a class="pe-link-task" href="{{ frappe.utils.get_url_to_form('Task', phase.name) }}" title="Abrir fase en ERPNext">{{ phase.subject }}</a></h3><span class="pe-task-code"><a class="pe-link-task" href="{{ frappe.utils.get_url_to_form('Task', phase.name) }}">{{ phase.name }}</a></span></td>
                <td class="pe-phase-kpi">
                  Avance: <strong>{{ frappe.format(phase.progress or 0, {'fieldtype': 'Percent'}) }}</strong> ·
                  Tasks directas: <strong>{{ phase_leaf_rows|length }}</strong> ·
                  Terminadas: <strong>{{ phase_done|length }}</strong> ·
                  Vencidas: <strong>{{ phase_overdue|length }}</strong>
                </td>
              </tr>
            </table>
            <div class="pe-phase-bars">
              <table>
                <tr>
                  <td class="bar-label">Avance</td>
                  <td><div class="pe-bar-track"><div class="pe-bar-fill actual" style="width: {{ '%.2f' | format(phase.progress or 0) }}%"></div></div></td>
                  <td class="bar-value">{{ '%.1f' | format(phase.progress or 0) }}%</td>
                </tr>
              </table>
            </div>
          </div>
        </div>
      {% endfor %}
    {% else %}
      <div class="pe-notes">El Project no utiliza Tasks padre marcadas como grupo. Las actividades se resumen a continuación.</div>
    {% endif %}

    {% if top_leaf_tasks %}
      {% set orphan_done = top_leaf_tasks | selectattr('status', 'equalto', 'Completed') | list %}
      {% set orphan_overdue = top_leaf_tasks | selectattr('status', 'equalto', 'Overdue') | list %}
      <div class="pe-small-title">Actividades sin fase padre</div>
      <table class="pe-meta">
        <tr>
          <th>Tasks</th><td>{{ top_leaf_tasks|length }}</td>
          <th>Terminadas</th><td>{{ orphan_done|length }}</td>
          <th>Vencidas</th><td>{{ orphan_overdue|length }}</td>
        </tr>
      </table>
    {% endif %}
  </div>

  <div class="pe-footnote">
    Generado desde ERPNext con datos nativos de Project y Task. El avance general es el avance oficial del proyecto (Project.percent_complete) según su método de cálculo. El avance por fase usa el progreso nativo de la Task de grupo. Las fechas y horas reales dependen del registro de Timesheets. Los enlaces de Tasks abren el documento correspondiente.
  </div>
</div>
